const s = require('node:sqlite');
const db = new s.DatabaseSync('/bench/home/work/.codegraph/codegraph.db');
const q = \`
SELECT n.name, n.qualified_name, n.file_path, n.start_line, COUNT(DISTINCT e.source) AS fanin, COUNT(*) AS calls
FROM edges e JOIN nodes n ON n.id = e.target
WHERE e.kind = 'calls'
  AND n.file_path LIKE 'internal/%'
  AND n.kind IN ('function','method')
GROUP BY n.id
ORDER BY fanin DESC
LIMIT 15\`;
for (const r of db.prepare(q).all())
  console.log(r.fanin, r.calls, r.name, r.file_path+':'+r.start_line);
" 2>/dev/null

